[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "expenseReportSurface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "expenseReportSurface",
      "value": {
        "expenses": [
          {
            "category": "Rent",
            "amount": "$1,500.00",
            "percentage": "51.4%"
          },
          {
            "category": "Groceries",
            "amount": "$600.00",
            "percentage": "20.5%"
          },
          {
            "category": "Dining Out",
            "amount": "$300.00",
            "percentage": "10.3%"
          },
          {
            "category": "Utilities",
            "amount": "$250.00",
            "percentage": "8.6%"
          },
          {
            "category": "Insurance",
            "amount": "$150.00",
            "percentage": "5.1%"
          },
          {
            "category": "Transport",
            "amount": "$120.00",
            "percentage": "4.1%"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "expenseReportSurface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "header",
                "type": "Text",
                "properties": {
                  "text": "Expense Summary: January 2024",
                  "style": "title"
                }
              },
              {
                "id": "assumptions",
                "type": "Text",
                "properties": {
                  "text": "Assumptions:\n- The currency is United States Dollar ($).\n- The provided list of expenses is the complete set for the specified month.",
                  "style": "caption"
                }
              },
              {
                "id": "summaryCard",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "summaryRow",
                    "type": "Row",
                    "properties": {
                      "spacing": "medium",
                      "crossAxisAlignment": "center",
                      "children": [
                        {
                          "id": "summaryIcon",
                          "type": "Icon",
                          "properties": {
                            "icon": "/icons/finance/dollar-circle.png",
                            "size": "large"
                          }
                        },
                        {
                          "id": "summaryDetails",
                          "type": "Column",
                          "properties": {
                            "children": [
                              {
                                "id": "summaryTitle",
                                "type": "Text",
                                "properties": {
                                  "text": "Total Monthly Expenses",
                                  "style": "headline"
                                }
                              },
                              {
                                "id": "summaryAmount",
                                "type": "Text",
                                "properties": {
                                  "text": "$2,920.00",
                                  "style": "title"
                                }
                              },
                              {
                                "id": "summaryDescription",
                                "type": "Text",
                                "properties": {
                                  "text": "This is the sum of all expense categories for January 2024.",
                                  "style": "body"
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "viewTabs",
                "type": "Tabs",
                "properties": {
                  "tabs": [
                    {
                      "label": "Expense Distribution",
                      "childId": "pieChart"
                    },
                    {
                      "label": "Detailed Breakdown",
                      "childId": "detailsList"
                    }
                  ]
                }
              },
              {
                "id": "pieChart",
                "type": "PieChart",
                "properties": {
                  "data": [
                    {
                      "label": "Rent",
                      "value": 1500
                    },
                    {
                      "label": "Groceries",
                      "value": 600
                    },
                    {
                      "label": "Dining Out",
                      "value": 300
                    },
                    {
                      "label": "Utilities",
                      "value": 250
                    },
                    {
                      "label": "Insurance",
                      "value": 150
                    },
                    {
                      "label": "Transport",
                      "value": 120
                    }
                  ]
                }
              },
              {
                "id": "detailsList",
                "type": "List",
                "properties": {
                  "visible": false,
                  "binding": "dataModel.expenses",
                  "templateChildId": "expenseRowTemplate",
                  "header": {
                    "id": "tableHeader",
                    "type": "Row",
                    "properties": {
                      "children": [
                        {
                          "id": "headerCategory",
                          "type": "Text",
                          "properties": {
                            "text": "Category",
                            "style": "label",
                            "fontWeight": "bold"
                          }
                        },
                        {
                          "id": "headerSpacer",
                          "type": "Spacer",
                          "properties": {}
                        },
                        {
                          "id": "headerAmount",
                          "type": "Text",
                          "properties": {
                            "text": "Amount",
                            "style": "label",
                            "fontWeight": "bold"
                          }
                        },
                        {
                          "id": "headerPercentage",
                          "type": "Text",
                          "properties": {
                            "text": "Percentage",
                            "style": "label",
                            "fontWeight": "bold",
                            "width": "80px",
                            "textAlign": "end"
                          }
                        }
                      ]
                    }
                  },
                  "footer": {
                    "id": "tableFooter",
                    "type": "Row",
                    "properties": {
                      "children": [
                        {
                          "id": "footerCategory",
                          "type": "Text",
                          "properties": {
                            "text": "Total",
                            "style": "label",
                            "fontWeight": "bold"
                          }
                        },
                        {
                          "id": "footerSpacer",
                          "type": "Spacer",
                          "properties": {}
                        },
                        {
                          "id": "footerAmount",
                          "type": "Text",
                          "properties": {
                            "text": "$2,920.00",
                            "style": "label",
                            "fontWeight": "bold"
                          }
                        },
                        {
                          "id": "footerPercentage",
                          "type": "Text",
                          "properties": {
                            "text": "100.0%",
                            "style": "label",
                            "fontWeight": "bold",
                            "width": "80px",
                            "textAlign": "end"
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "expenseRowTemplate",
                "type": "Row",
                "properties": {
                  "template": true,
                  "children": [
                    {
                      "id": "itemCategory",
                      "type": "Text",
                      "properties": {
                        "binding": "item.category"
                      }
                    },
                    {
                      "id": "itemSpacer",
                      "type": "Spacer",
                      "properties": {}
                    },
                    {
                      "id": "itemAmount",
                      "type": "Text",
                      "properties": {
                        "binding": "item.amount"
                      }
                    },
                    {
                      "id": "itemPercentage",
                      "type": "Text",
                      "properties": {
                        "binding": "item.percentage",
                        "width": "80px",
                        "textAlign": "end"
                      }
                    }
                  ]
                }
              },
              {
                "id": "divider",
                "type": "Divider",
                "properties": {}
              },
              {
                "id": "actionsTitle",
                "type": "Text",
                "properties": {
                  "text": "Quick Actions",
                  "style": "headline"
                }
              },
              {
                "id": "actionsContainer",
                "type": "Row",
                "properties": {
                  "spacing": "small",
                  "children": [
                    {
                      "id": "budgetButton",
                      "type": "Button",
                      "properties": {
                        "label": "Create a Budget for February",
                        "action": {
                          "functionCall": {
                            "call": "showToast",
                            "args": [
                              "Feature to create a budget is coming soon!"
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tipsButton",
                      "type": "Button",
                      "properties": {
                        "label": "Find Tips for Saving Money",
                        "action": {
                          "functionCall": {
                            "call": "openUrl",
                            "args": [
                              "https://www.investopedia.com/personal-finance/tips-saving-money/"
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "exportButton",
                      "type": "Button",
                      "properties": {
                        "label": "Export Report as CSV",
                        "action": {
                          "functionCall": {
                            "call": "showToast",
                            "args": [
                              "Exporting report..."
                            ]
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  }
]
